sys_script_client.script:
function onLoad() {
	g_form.setDisplay('state',false);
   if(g_form.getValue('state') == '-5' || g_form.getValue('state') == '8'){
	g_form.showRelatedList('x_1040502_nsc_pe_0_approval_routing_preview');
	g_form.showRelatedList('u_approval_history');
   }
//    else{
// 	g_form.hideRelatedList('x_1040502_nsc_pe_0_approval_routing_preview');
// 	g_form.hideRelatedList('u_approval_history');
// 	g_form.hideRelatedList('x_1040502_wbs_change_history');
//    }
   else if((g_form.getValue('state') == '8' && g_scratchpad.reason == true) || (g_form.getValue('state') == '10' && g_scratchpad.reason == true) || (g_form.getValue('state') == '-5' && g_scratchpad.reason == true)){
	g_form.showRelatedList('u_approval_history');
	g_form.showRelatedList('x_1040502_wbs_change_history');
   }
   else{
	g_form.hideRelatedList('x_1040502_wbs_change_history');
	g_form.hideRelatedList('x_1040502_nsc_pe_0_approval_routing_preview');
	g_form.hideRelatedList('u_approval_history');
	g_form.hideRelatedList('x_1040502_wbs_change_history');
   }
}
